algorithms.pseudocode:
function DIAL_CAPACITY(rho, gamma):
    require 0 <= rho < 1
    if gamma >= rho^2:
        return INFINITY                # ceiling looser than the readings demand
    return floor( (1 - gamma) / (rho^2 - gamma) )

function DIAL_THRESHOLD(rho, k):        # k >= 2
    return (k*rho^2 - 1) / (k - 1)

function STAIRCASE(rho, kmax):
    S <- empty list
    for k = 2 .. kmax:
        S.append( (k, DIAL_THRESHOLD(rho, k)) )
    return S                            # strictly increasing in k

function IS_ADMISSIBLE(rho, gamma, k):
    return k*rho^2 <= 1 + (k-1)*gamma

function ANTIVARY(x, y):
    for all i, j:
        if (x_i - x_j) * (y_i - y_j) > 0: return FALSE
    return TRUE

function AGGREGATE_CERTIFICATE(alpha[1..r], P, products?, correlations?):
    E <- sum_i alpha_i^2                       # pooled advantage energy
    floor_uncond <- E / (2 * r * (1 - P))      # valid always
    report.max_admissible_cmin <- 1 - floor_uncond
    if products given:
        slack <- 2 * ( r - sum_i products_i )
        report.exact_worst_case_floor <- E / slack
        if correlations given:
            decorr   <- [1 - c_i]
            headroom <- [1 - products_i]
            if ANTIVARY(decorr, headroom):
                cbar <- mean(correlations)
                report.mean_based_budget <- 2*(1-cbar)*(r - sum_i products_i)
                report.mean_based_budget_valid <- TRUE
            else:
                report.mean_based_budget_valid <- FALSE   # averaging is unsound
    return report
